from collections import deque

def comps8(g):
 h=len(g); w=len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c] and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); cells=[]
    while q:
     x,y=q.pop(); cells.append((x,y))
     for dx in (-1,0,1):
      for dy in (-1,0,1):
       z=(x+dx,y+dy)
       if (dx or dy) and 0<=z[0]<h and 0<=z[1]<w and g[z[0]][z[1]] and z not in seen:
        seen.add(z); q.append(z)
    out.append(cells)
 return out

